"""Lazy CARLA flashing-yellow source selection and readback controller.

The supplied official-control record is a planning premise. A CARLA traffic
light and its affected lane waypoints establish only simulated lane linkage.
"""
from dataclasses import dataclass
from math import cos, radians, sin


@dataclass(frozen=True)
class Approach:
    light: object
    waypoint: object
    junction_id: int
    direction: str
    opendrive_id: str


def _xy(waypoint):
    p = waypoint.transform.location
    return (float(p.x), float(p.y))


def _direction(waypoint):
    yaw = radians(float(waypoint.transform.rotation.yaw))
    x, y = cos(yaw), sin(yaw)
    if abs(x) < .75 or abs(y) > .66:
        return None
    return 'east' if x > 0 else 'west'


def _junction_id(waypoint):
    """Follow the governed lane toward its first intersection."""
    cursor = waypoint
    for _ in range(16):
        junction = cursor.get_junction()
        if junction is not None:
            return int(junction.id)
        successors = cursor.next(2.0)
        if len(successors) != 1:
            return None
        cursor = successors[0]
    return None


def discover_approaches(lights, official_control_source):
    """Return an east/west pair linked by one simulated junction.

    Require an identified control premise, source OpenDRIVE identifiers, and
    affected lane waypoints. Ambiguous maps fail closed for manual route choice.
    """
    if not official_control_source or not str(official_control_source).strip():
        raise ValueError('missing official-control source premise')
    by_junction = {}
    for light in lights:
        od_id = str(light.get_opendrive_id() or '').strip()
        if not od_id:
            continue
        for waypoint in light.get_affected_lane_waypoints():
            direction = _direction(waypoint)
            junction_id = _junction_id(waypoint)
            if direction is None or junction_id is None:
                continue
            by_junction.setdefault(junction_id, {}).setdefault(direction, []).append(
                Approach(light, waypoint, junction_id, direction, od_id))
    for junction_id in sorted(by_junction):
        sides = by_junction[junction_id]
        if 'east' in sides and 'west' in sides:
            east, west = sides['east'][0], sides['west'][0]
            if east.light.id == west.light.id:
                continue
            return {'east': east, 'west': west}
    raise ValueError('no distinct opposing governed heads at one junction')


def route_for(approach, before_m=70.0, after_m=70.0):
    """Use the governed lane waypoint, not world-origin coordinates."""
    if before_m <= 0 or after_m <= 0:
        raise ValueError('route distances must be positive')
    starts = approach.waypoint.previous(before_m)
    ends = approach.waypoint.next(after_m)
    if len(starts) != 1 or len(ends) != 1:
        raise ValueError('governed lane has ambiguous route')
    start, end = starts[0], ends[0]
    x0, _ = _xy(start)
    x1, _ = _xy(end)
    if (x1 - x0) * (1 if approach.direction == 'east' else -1) <= 0:
        raise ValueError('route does not follow governed approach direction')
    return (start.transform, end.transform)


def crossing_route(world_map, junction_id, sample_step_m=5.0,
                   before_m=65.0, after_m=65.0):
    """Find one perpendicular travel lane that traverses this same junction."""
    candidates = []
    for waypoint in world_map.generate_waypoints(sample_step_m):
        if _junction_id(waypoint) != junction_id:
            continue
        yaw = radians(float(waypoint.transform.rotation.yaw))
        if abs(sin(yaw)) < .75 or abs(cos(yaw)) > .66:
            continue
        starts, ends = waypoint.previous(before_m), waypoint.next(after_m)
        if len(starts) != 1 or len(ends) != 1:
            continue
        x0, y0 = _xy(starts[0]); x1, y1 = _xy(ends[0])
        if abs(y1-y0) < before_m/2:
            continue
        candidates.append((int(waypoint.road_id), int(waypoint.lane_id),
                           starts[0].transform, ends[0].transform))
    if not candidates:
        raise ValueError('no traversing perpendicular crossing lane at selected junction')
    candidates.sort(key=lambda x: (x[0], x[1]))
    road_id, lane_id, start, end = candidates[0]
    return {'road_id': road_id, 'lane_id': lane_id, 'start': start, 'end': end}


def construct_native(world, case, official_control_source, blueprint_id='vehicle.tesla.model3',
                     *, approach_before_m=70.0, spawn_z_offset_m=0.0):
    """Place the selected participants on map governed lanes.

    The caller owns returned vehicle actors and must destroy them in a finally
    block. This function cleans up actors itself if construction fails.
    """
    if case.direction not in ('east', 'west'):
        raise ValueError('unsupported approach direction')
    approaches = discover_approaches(
        world.get_actors().filter('traffic.traffic_light*'), official_control_source)
    selected = approaches[case.direction]
    if not 0 <= spawn_z_offset_m <= .5:
        raise ValueError('spawn height adjustment outside engineering bounds')
    ego_route = route_for(selected, before_m=approach_before_m)
    cross_route = (crossing_route(world.get_map(), selected.junction_id)
                   if case.crossing_vehicle else None)
    blueprint = world.get_blueprint_library().find(blueprint_id)
    owned = []
    try:
        ego_start = ego_route[0]
        if spawn_z_offset_m:
            from copy import deepcopy
            ego_start = deepcopy(ego_start)
            ego_start.location.z += spawn_z_offset_m
        ego = world.try_spawn_actor(blueprint, ego_start)
        if ego is None:
            raise ValueError('ego Native actor spawn failed')
        owned.append(ego)
        crossing = None
        if cross_route is not None:
            crossing_start = cross_route['start']
            if spawn_z_offset_m:
                from copy import deepcopy
                crossing_start = deepcopy(crossing_start)
                crossing_start.location.z += spawn_z_offset_m
            crossing = world.try_spawn_actor(blueprint, crossing_start)
            if crossing is None:
                raise ValueError('crossing Native actor spawn failed')
            owned.append(crossing)
        return {'approaches': approaches, 'selected': selected,
                'light': selected.light, 'ego_route': ego_route,
                'crossing_route': cross_route, 'ego': ego,
                'crossing': crossing, 'owned': owned,
                'official_control_source': official_control_source}
    except BaseException:
        for actor in reversed(owned):
            actor.destroy()
        raise


class FlashController:
    """Set and verify an existing Native light state on every capture tick."""
    def __init__(self, light, traffic_light_state, period_s=.5):
        if period_s <= 0:
            raise ValueError('period must be positive')
        self.light = light
        self.state = traffic_light_state
        self.period_s = period_s
        self.initial_state = None

    def __enter__(self):
        self.initial_state = self.light.get_state()
        return self

    def set_at(self, time_s):
        if self.initial_state is None:
            raise RuntimeError('controller not entered')
        if time_s < 0:
            raise ValueError('negative capture time')
        on = (time_s % self.period_s) < self.period_s / 2
        target = self.state.Yellow if on else self.state.Off
        self.light.set_state(target)
        observed = self.light.get_state()
        if observed != target:
            raise ValueError('flashing-yellow Native readback mismatch')
        return {'yellow_commanded': on, 'native_light_state': str(observed),
                'light_actor_id': int(self.light.id)}

    def __exit__(self, exc_type, exc, tb):
        if self.initial_state is not None:
            self.light.set_state(self.initial_state)
            if self.light.get_state() != self.initial_state:
                raise ValueError('traffic-light restoration readback mismatch')
            self.initial_state = None

"""CPU construction and observation for the flashing-yellow intersection.

The selected blink rate and approach speeds are engineering samples, not legal
interpretations of 'rapid' or 'with caution'. Official status is a sourced
premise and cannot be established by the lamp geometry alone.
"""
from dataclasses import dataclass
from math import hypot

@dataclass(frozen=True)
class Case:
    name: str
    approach_target_mps: float
    crossing_vehicle: bool
    direction: str

CASES={
 'east_cautious_approach':Case('east_cautious_approach',4.0,True,'east'),
 'east_faster_approach':Case('east_faster_approach',9.0,True,'east'),
 'east_clear_approach':Case('east_clear_approach',4.0,False,'east'),
 'west_cautious_approach':Case('west_cautious_approach',4.0,True,'west'),
}

def lamp_on(time_s, phase_s=0.0, cycle_s=0.5):
    """Engineering 2 Hz square wave; retained readback must verify realization."""
    if time_s < 0 or cycle_s <= 0:
        raise ValueError('invalid lamp timing')
    return ((time_s+phase_s)%cycle_s) < cycle_s/2


def construct(adapter, case):
    """Make an actual signal head and opposing intersection approaches."""
    if case.direction not in ('east','west'):
        raise ValueError('unsupported approach direction')
    intersection=adapter.intersection(through_lanes=2,cross_lanes=2)
    start=(-70.0,0.0) if case.direction=='east' else (70.0,0.0)
    end=(70.0,0.0) if case.direction=='east' else (-70.0,0.0)
    head=adapter.signal_head(lens='yellow', illuminated=True,
                             mounted_xy=(-12.0,-3.0) if case.direction=='east' else (12.0,3.0),
                             governs_approach=case.direction)
    device=adapter.official_control_device(type='intersection_advance_warning',
                                             linked_signal=head)
    ego=adapter.vehicle(role='ego',route=[start,end],target_mps=case.approach_target_mps)
    crossing=None
    if case.crossing_vehicle:
        crossing=adapter.vehicle(role='crossing',route=[(0.0,-65.0),(0.0,65.0)],
                                 target_mps=6.0)
    return {'intersection':intersection,'signal_head':head,'official_device':device,
            'ego':ego,'crossing':crossing}


def measure(samples):
    """Join physical lamp readback and participant trajectories at 20 Hz."""
    if len(samples)<2: raise ValueError('at least two original samples required')
    rows=[];last=None
    for s in samples:
        t=s['time_s']
        if last is not None and (t<=last or abs(t-last-.05)>.005):
            raise ValueError('non-20Hz original time')
        last=t
        if s.get('signal_head_visible') is not True or type(s.get('yellow_lens_on')) is not bool:
            raise ValueError('missing physical flashing-yellow readback')
        if not s.get('official_device_source'):
            raise ValueError('official-device premise lacks source')
        if not s.get('ego_valid'):
            raise ValueError('missing ego original state')
        distance=hypot(*s['ego_center_xy'])
        row={'time_s':t,'ego_speed_mps':s['ego_speed_mps'],
             'ego_center_distance_to_conflict_m':distance,
             'yellow_lens_on':s['yellow_lens_on'],
             'signal_head_visible':s['signal_head_visible'],
             'crossing_valid':s.get('crossing_valid') is True,
             'source':s['source']}
        if row['crossing_valid']:
            row['crossing_center_distance_to_conflict_m']=hypot(*s['crossing_center_xy'])
        rows.append(row)
    if len(set(x['yellow_lens_on'] for x in rows))<2:
        raise ValueError('no observed intermittent illumination')
    return {'samples':rows,'duration_s':rows[-1]['time_s']-rows[0]['time_s'],
            'legal_caution_judgment':'unresolved'}


def audit_comparison(a,b,differences):
    if not a.get('samples') or not b.get('samples'):
        raise ValueError('missing original measurements')
    for key in ('map_hash','signal_head_hash','official_device_source','blink_period_s',
                'camera_plan_hash','duration_s'):
        if a.get(key) is None or a.get(key)!=b.get(key):
            raise ValueError('fixed condition differs: '+key)
    changed={key for key in ('approach_target_mps','crossing_vehicle','direction')
             if a.get(key)!=b.get(key)}
    if changed!=set(differences):
        raise ValueError('undeclared or missing deliberate difference')
    return {'fixed_conditions_checked':True,'legal_caution_judgment':'unresolved'}

"""Four original-frame RGB sources for the flashing-yellow intersection delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer statutory caution or physical signal visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-10.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 100),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-5.0, 2.5, 3.5), (-8.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans():
    return [CameraPlan(name, *spec) for name, spec in CAMERAS.items()]


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class SignalCameraCapture:
    def __init__(self, world, carla_module, subject, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans():
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Retain original Native signal and participant samples at each camera joined tick."""
import json
from math import hypot
from pathlib import Path


def _state(actor):
    if actor is None or not actor.is_alive:
        raise ValueError('required participant absent from Native world')
    p = actor.get_transform().location
    v = actor.get_velocity()
    return {'actor_id': int(actor.id), 'center_xy': [float(p.x), float(p.y)],
            'speed_mps': hypot(v.x, v.y)}


class SignalCaptureSession:
    def __init__(self, output, pipeline_capture, scene, context):
        from worker_exchange.native_output import FrameMap
        root = Path(output)
        if not context.get('official_control_source'):
            raise ValueError('official-control premise requires a source record')
        if context.get('selected_direction') != scene['selected'].direction:
            raise ValueError('selected governed direction differs')
        if context.get('opendrive_id') != scene['selected'].opendrive_id:
            raise ValueError('source OpenDRIVE ID differs')
        for name in ('signal_context.json', 'signal_state.jsonl',
                     'participant_state.jsonl', 'video_frames.jsonl'):
            if (root/name).exists():
                raise ValueError('retain prior source; use fresh attempt: ' + name)
        (root/'signal_context.json').write_text(json.dumps(context, indent=2)+'\n')
        self.signal = (root/'signal_state.jsonl').open('x')
        self.participants = (root/'participant_state.jsonl').open('x')
        self.frames = FrameMap(root/'video_frames.jsonl')
        self.pipeline = pipeline_capture
        self.scene = scene
        self.closed = False

    def capture(self, frame, time_s, flash_row):
        if self.closed:
            raise ValueError('capture session closed')
        if flash_row['light_actor_id'] != self.scene['light'].id:
            raise ValueError('flashing controller belongs to another head')
        original = self.pipeline.capture(frame, time_s)
        if (original.get('frame'), original.get('time_s')) != (frame, time_s):
            raise ValueError('PipelineCapture returned another original tick')
        signal = {'frame': frame, 'time_s': time_s,
                  'light_actor_id': flash_row['light_actor_id'],
                  'opendrive_id': self.scene['selected'].opendrive_id,
                  'yellow_commanded': flash_row['yellow_commanded'],
                  'native_light_state': flash_row['native_light_state'],
                  'lens_pixel_visible': None}
        participants = {'frame': frame, 'time_s': time_s,
                        'ego': _state(self.scene['ego']),
                        'crossing': (_state(self.scene['crossing'])
                                     if self.scene['crossing'] is not None else None)}
        self.signal.write(json.dumps(signal)+'\n'); self.signal.flush()
        self.participants.write(json.dumps(participants)+'\n'); self.participants.flush()
        self.frames.append(frame, time_s)
        return original

    def close(self):
        if not self.closed:
            self.closed = True
            self.frames.close(); self.signal.close(); self.participants.close()

"""Independent fixed-condition audit over saved C111273 original sources."""
import argparse
import hashlib
import json
from pathlib import Path

from flashing_yellow import CASES
from signal_finalizer import analyze


PAIRS = {
    'approach_speed_sample': ('east_cautious_approach', 'east_faster_approach',
                              {'approach_target_mps'}),
    'crossing_traffic_context': ('east_cautious_approach', 'east_clear_approach',
                                 {'crossing_vehicle'}),
    'approach_direction': ('east_cautious_approach', 'west_cautious_approach',
                           {'direction'}),
}


def _read(path):
    return json.loads(Path(path).read_text())


def audit(comparison_id, first, second):
    if comparison_id not in PAIRS:
        raise ValueError('Unknown frozen comparison')
    expected_a, expected_b, expected_diff = PAIRS[comparison_id]
    reports = [analyze(first, write_channels=False),
               analyze(second, write_channels=False)]
    if not reports[0]['case_id'].endswith('__'+expected_a) or not reports[1]['case_id'].endswith('__'+expected_b):
        raise ValueError('Wrong exact comparison cases')
    roots = [Path(first), Path(second)]
    configs = [_read(root/'config.json') for root in roots]
    contexts = [_read(root/'signal_context.json') for root in roots]
    if any(not context.get('junction_id') or not context.get('official_control_source')
           for context in contexts):
        raise ValueError('Missing fixed junction or control source')
    for key in ('junction_id', 'official_control_source', 'flash_period_s'):
        if contexts[0].get(key) != contexts[1].get(key):
            raise ValueError('Fixed condition differs: '+key)
    for key in ('rate_hz', 'frames', 'duration_s', 'cameras'):
        if configs[0].get(key) != configs[1].get(key):
            raise ValueError('Fixed condition differs: '+key)
    changed = {key for key, a, b in (
        ('approach_target_mps', CASES[expected_a].approach_target_mps,
         CASES[expected_b].approach_target_mps),
        ('crossing_vehicle', CASES[expected_a].crossing_vehicle,
         CASES[expected_b].crossing_vehicle),
        ('direction', CASES[expected_a].direction, CASES[expected_b].direction)) if a != b}
    if changed != expected_diff:
        raise ValueError('Declared case difference does not match exact cases')
    for config, branch in zip(configs, (expected_a, expected_b)):
        if config.get('target_speed_mps') != CASES[branch].approach_target_mps:
            raise ValueError('Requested speed differs from exact case')
    source_hashes = []
    for root, report in zip(roots, reports):
        hashes = report['measurements']['flashing_yellow']['value']['source_hashes']
        for name, digest in hashes.items():
            if hashlib.sha256((root/name).read_bytes()).hexdigest() != digest:
                raise ValueError('Source changed during comparison audit')
        source_hashes.append(hashes)
    return {'format': 'worker-signal-comparison-audit',
            'comparison_id': comparison_id,
            'case_ids': [report['case_id'] for report in reports],
            'fixed_conditions_checked': True,
            'deliberate_differences': sorted(changed),
            'source_hashes': source_hashes,
            'legal_caution_judgment': 'unresolved',
            'physical_acceptance_claimed': False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--comparison', required=True)
    parser.add_argument('--first', required=True)
    parser.add_argument('--second', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    path = Path(args.output)
    if path.exists(): raise ValueError('Retain prior comparison audit')
    path.write_text(json.dumps(audit(args.comparison, args.first, args.second),
                               indent=2)+'\n')


if __name__ == '__main__': main()
